function gfMul(a: number, b: number): number {
  if (a === 0 || b === 0) return 0
  return EXP_TABLE[(LOG_TABLE[a]! + LOG_TABLE[b]!) % 255]!
}

function gfDiv(a: number, b: number): number {
  if (a === 0) return 0
  return EXP_TABLE[(LOG_TABLE[a]! - LOG_TABLE[b]! + 255) % 255]!
}

function gfExp(a: number, n: number): number {
  if (n === 0) return 1
  if (a === 0) return 0
  return EXP_TABLE[(LOG_TABLE[a]! * n) % 255]!
}

// Matrix over GF(2^8), stored row-major in a flat Uint8Array
class GFMatrix {
  readonly rows: number
  readonly cols: number
  private data: Uint8Array

  constructor(rows: number, cols: number, data?: Uint8Array) {
    this.rows = rows
    this.cols = cols
    this.data = data ?? new Uint8Array(rows * cols)
  }

  get(r: number, c: number): number {
    return this.data[r * this.cols + c]!
  }

  set(r: number, c: number, v: number): void {
    this.data[r * this.cols + c] = v
  }

  static identity(n: number): GFMatrix {
    const m = new GFMatrix(n, n)
    for (let i = 0; i < n; i++) m.set(i, i, 1)
    return m
  }

  // vandermonde[r][c] = gfExp(r, c)
  static vandermonde(rows: number, cols: number): GFMatrix {
    const m = new GFMatrix(rows, cols)
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        m.set(r, c, gfExp(r, c))
      }
    }
    return m
  }

  multiply(right: GFMatrix): GFMatrix {
    const result = new GFMatrix(this.rows, right.cols)
    for (let r = 0; r < this.rows; r++) {
      for (let c = 0; c < right.cols; c++) {
        let val = 0
        for (let i = 0; i < this.cols; i++) {
          val ^= gfMul(this.get(r, i), right.get(i, c))
        }
        result.set(r, c, val)
      }
    }
    return result
  }

  augment(right: GFMatrix): GFMatrix {
    const result = new GFMatrix(this.rows, this.cols + right.cols)
    for (let r = 0; r < this.rows; r++) {
      for (let c = 0; c < this.cols; c++) result.set(r, c, this.get(r, c))
      for (let c = 0; c < right.cols; c++) result.set(r, this.cols + c, right.get(r, c))
    }
    return result
  }

  subMatrix(rmin: number, cmin: number, rmax: number, cmax: number): GFMatrix {
    const result = new GFMatrix(rmax - rmin, cmax - cmin)
    for (let r = rmin; r < rmax; r++) {
      for (let c = cmin; c < cmax; c++) {
        result.set(r - rmin, c - cmin, this.get(r, c))
      }
    }
    return result
  }

  swapRows(r1: number, r2: number): void {
    for (let c = 0; c < this.cols; c++) {
      const tmp = this.get(r1, c)
      this.set(r1, c, this.get(r2, c))
      this.set(r2, c, tmp)
    }
  }

  invert(): GFMatrix {
    const size = this.rows
    const work = this.augment(GFMatrix.identity(size))
    work.gaussianElimination()
    return work.subMatrix(0, size, size, size * 2)
  }

  private gaussianElimination(): void {
    const rows = this.rows
    const cols = this.cols
    for (let r = 0; r < rows; r++) {
      if (this.get(r, r) === 0) {
        for (let rowBelow = r + 1; rowBelow < rows; rowBelow++) {
          if (this.get(rowBelow, r) !== 0) {
            this.swapRows(r, rowBelow)
            break
          }
        }
      }
      if (this.get(r, r) === 0) throw new Error('matrix is singular')
      if (this.get(r, r) !== 1) {
        const scale = gfDiv(1, this.get(r, r))
        for (let c = 0; c < cols; c++) {
          this.set(r, c, gfMul(this.get(r, c), scale))
        }
      }
      for (let rowBelow = r + 1; rowBelow < rows; rowBelow++) {
        if (this.get(rowBelow, r) !== 0) {
          const scale = this.get(rowBelow, r)
          for (let c = 0; c < cols; c++) {
            this.set(rowBelow, c, this.get(rowBelow, c) ^ gfMul(scale, this.get(r, c)))
          }
        }
      }
    }
    for (let d = 0; d < rows; d++) {
      for (let rowAbove = 0; rowAbove < d; rowAbove++) {
        if (this.get(rowAbove, d) !== 0) {
          const scale = this.get(rowAbove, d)
          for (let c = 0; c < cols; c++) {
            this.set(rowAbove, c, this.get(rowAbove, c) ^ gfMul(scale, this.get(d, c)))
          }
        }
      }
    }
  }
}

// Builds the encoding matrix (Vandermonde × inverse of top square). The top
// `dataShards` rows form the identity (systematic code) so data shards pass
// through unchanged; the remaining rows are the parity rows. This is the
// default matrix from klauspost/reedsolomon's buildMatrix function.
const matrixCache = new Map<string, GFMatrix>()

function buildMatrix(dataShards: number, parityShards: number): GFMatrix {
  const key = `${dataShards},${parityShards}`
  let matrix = matrixCache.get(key)
  if (!matrix) {
    const totalShards = dataShards + parityShards
    const vm = GFMatrix.vandermonde(totalShards, dataShards)
    const top = vm.subMatrix(0, 0, dataShards, dataShards)
    matrix = vm.multiply(top.invert())
    matrixCache.set(key, matrix)
  }
  return matrix
}

function getParityRows(dataShards: number, parityShards: number): number[][] {
  const matrix = buildMatrix(dataShards, parityShards)
  const rows: number[][] = []
  for (let i = 0; i < parityShards; i++) {
    const row: number[] = []
    for (let c = 0; c < dataShards; c++) row.push(matrix.get(dataShards + i, c))
    rows.push(row)
  }
  return rows
}

/**
 * Encodes `data` shards (all the same length) into `parityCount` parity
 * shards of that same length, using GF(2^8) Reed-Solomon. Data shards are
 * not modified. Compatible with klauspost/reedsolomon's default encoder -
 * the same scheme real Bee nodes use, so this interoperates with them.
 */
export function rsEncode(data: Uint8Array[], parityCount: number): Uint8Array[] {
  if (parityCount === 0) return []
  const dataCount = data.length
  const shardSize = data[0]!.length
  const rows = getParityRows(dataCount, parityCount)
  return rows.map(row => {
    const parity = new Uint8Array(shardSize)
    for (let j = 0; j < shardSize; j++) {
      let val = 0
      for (let k = 0; k < dataCount; k++) {
        val ^= gfMul(row[k]!, data[k]![j]!)
      }
      parity[j] = val
    }
    return parity
  })
}

/**
 * Reconstructs missing DATA shards from a mix of available data and parity
 * shards using GF(2^8) Reed-Solomon (erasure decoding) — the inverse of
 * `rsEncode`. `shards` is index-aligned and `dataCount + parityCount` long:
 * data shards first, then parity shards. Present shards are equal-length
 * Uint8Arrays; missing shards are `null`. Returns the `dataCount` data shards
 * with any missing ones reconstructed (present ones are returned as-is).
 * Throws if fewer than `dataCount` shards are present (unrecoverable).
 * Compatible with klauspost/reedsolomon, so it decodes data produced by real
 * Bee nodes.
 */
export function rsDecode(shards: (Uint8Array | null)[], dataCount: number, parityCount: number): Uint8Array[] {
  const totalCount = dataCount + parityCount
  if (shards.length !== totalCount) {
    throw new Error(`rsDecode: expected ${totalCount} shards, got ${shards.length}`)
  }

  // Fast path: every data shard is already present, nothing to reconstruct.
  let missingData = false
  for (let i = 0; i < dataCount; i++) {
    if (!shards[i]) {
      missingData = true
      break
    }
  }
  if (!missingData) return shards.slice(0, dataCount) as Uint8Array[]

  // Gather the first `dataCount` present shards to form a solvable system.
  const presentRows: number[] = []
  let shardSize = -1
  for (let i = 0; i < totalCount && presentRows.length < dataCount; i++) {
    const shard = shards[i]
    if (shard) {
      presentRows.push(i)
      if (shardSize < 0) shardSize = shard.length
    }
  }
  if (presentRows.length < dataCount) {
    throw new Error(`rsDecode: only ${presentRows.length} of ${dataCount} required shards present`)
  }

  // The decode matrix is the inverse of the encoding-matrix rows that
  // correspond to the present shards; data = decodeMatrix × presentShards.
  const matrix = buildMatrix(dataCount, parityCount)
  const sub = new GFMatrix(dataCount, dataCount)
  for (let r = 0; r < dataCount; r++) {
    for (let c = 0; c < dataCount; c++) sub.set(r, c, matrix.get(presentRows[r]!, c))
  }
  const decodeMatrix = sub.invert()

  const result: Uint8Array[] = []
  for (let i = 0; i < dataCount; i++) {
    const existing = shards[i]
    if (existing) {
      result.push(existing)
      continue
    }
    const out = new Uint8Array(shardSize)
    for (let j = 0; j < shardSize; j++) {
      let val = 0
      for (let r = 0; r < dataCount; r++) {
        val ^= gfMul(decodeMatrix.get(i, r), shards[presentRows[r]!]![j]!)
      }
      out[j] = val
    }
    result.push(out)
  }
  return result
}
